B.ahd=new A.tx(B.Sw,"Trazer a sua m\xfasica.","O Zywny n\xe3o traz partituras: elas chegam em bibliotecas que voc\xea instala. D\xe1 para transpor para um tom mais f\xe1cil, mudar o tamanho da nota\xe7\xe3o e escolher as cores.",null)
B.ahe=new A.tx(B.kI,"Ensinar do zero.","O curso inicial leva do teclado e da pauta at\xe9 uma pe\xe7a a duas m\xe3os. Professores podem escrever os seus pr\xf3prios cursos.",null)
B.ahf=new A.tx(B.wv,"Estudar com m\xe9todo.","Cada m\xfasica vira uma trilha de trechos curtos e etapas que se liberam como fases de um jogo, do devagar ao andamento real.",null)
B.ahg=new A.tx(B.dS,"Treinar no seu teclado.","Ligue um teclado MIDI e o Zywny acompanha cada nota que voc\xea toca: espera por voc\xea (modo espera) ou anda no ritmo da m\xfasica (tempo real), e mostra o que acertou e o que errou.",null)
